// === Tab: mySketch ===
/*
  Zen Pot Garden - Stone Platforms & Zen Pools
  A meditative generative art piece featuring:
  - Smooth flat stones under each pot
  - Zen pools/streams in the surrounding area
  - Faded blurry foreground branches for depth
  - Multiple funny-shaped pots with cool gradients
  - Warm gradient-shaded leaves
  - Proper depth layering
  - Click to generate a completely new garden
*/

// Branch parameters
let branches = [];
let foregroundBranches = [];
let maxDepth = 7;
let branchProbability = 0.85;
let leafProbability = 0.7;

// Multiple pots
let pots = [];
let stones = [];
let zenPools = [];

// Color palettes - EXPANDED COOL POTS
const POT_BASE_COLORS = [
  {start: '#1a2a4a', end: '#3a5a7a'},  // Deep blue
  {start: '#1a3a3a', end: '#4a7a7a'},  // Teal
  {start: '#2a1a4a', end: '#5a3a7a'},  // Purple
  {start: '#1a2a5a', end: '#4a5a8a'},  // Royal blue
  {start: '#0a2a3a', end: '#3a6a7a'},  // Ocean
  {start: '#2a3a5a', end: '#5a6a8a'},  // Steel blue
  {start: '#1a3a4a', end: '#4a6a7a'},  // Slate
  {start: '#2a1a3a', end: '#6a4a7a'},  // Mauve
  {start: '#0a3a3a', end: '#3a7a7a'},  // Dark teal
  {start: '#1a2a3a', end: '#4a5a6a'},  // Gunmetal
  {start: '#3a2a4a', end: '#6a4a8a'},  // Lavender
  {start: '#1a4a4a', end: '#3a7a7a'},  // Seafoam
  {start: '#2a1a5a', end: '#5a3a8a'},  // Indigo
  {start: '#0a3a4a', end: '#3a6a8a'},  // Denim
  {start: '#3a3a5a', end: '#6a6a8a'},  // Periwinkle
];

// EXPANDED WARM LEAF GRADIENTS
const LEAF_GRADIENTS = [
  {start: '#cc2233', end: '#ff6677'},  // Red to pink
  {start: '#dd3344', end: '#ff8899'},  // Coral
  {start: '#bb1122', end: '#ff4455'},  // Crimson
  {start: '#ee4455', end: '#ffaabb'},  // Rose
  {start: '#aa0022', end: '#ff3344'},  // Ruby
  {start: '#cc3344', end: '#ff7788'},  // Salmon
  {start: '#dd4455', end: '#ff9999'},  // Pinkish red
  {start: '#bb2233', end: '#ff6677'},  // Cherry
  {start: '#cc4455', end: '#ff8899'},  // Watermelon
  {start: '#dd5566', end: '#ffaabb'},  // Blush
  {start: '#cc2244', end: '#ff6688'},  // Berry
  {start: '#dd3355', end: '#ff7799'},  // Strawberry
  {start: '#bb1133', end: '#ff4455'},  // Fire
  {start: '#ee4455', end: '#ffbbaa'},  // Peach
  {start: '#cc4455', end: '#ff8899'},  // Coral pink
];

const BRANCH_COLORS = ['#5c3d2e', '#6b4c3b', '#4a3227', '#7a5a45', '#8b6b55', '#3d2517', '#9a7a5a'];

// Define pot shapes
const POT_SHAPES = [
  'classic', 'squat', 'tall', 'wavy', 'bulbous', 
  'hourglass', 'bowl', 'tapered', 'curvy', 'barrel'
];

class ForegroundBranch {
  constructor(x, y, angle, depth, maxDepth, length, branchWidth) {
    this.x = x;
    this.y = y;
    this.angle = angle;
    this.depth = depth;
    this.maxDepth = maxDepth;
    this.length = length;
    this.branchWidth = branchWidth;
    this.children = [];
    this.leaves = [];
    this.growth = 0;
    this.growthSpeed = random(0.01, 0.03);
    this.curveAmount = random(-0.5, 0.5);
    this.color = random(BRANCH_COLORS);
    this.blurAmount = random(5, 15);

    if (depth > maxDepth * 0.3 && random() < 0.6) {
      this.createLeaves();
    }
  }

  createLeaves() {
    let numLeaves = Math.floor(random(2, 5));
    for (let i = 0; i < numLeaves; i++) {
      let leafAngle = random(-0.8, 0.8);
      let leafSize = random(12, 25);
      let gradient = random(LEAF_GRADIENTS);
      let leafRotation = random(TWO_PI);

      let pos = random(0.3, 0.9);

      this.leaves.push({
        angle: leafAngle,
        size: leafSize,
        gradient: gradient,
        rotation: leafRotation,
        position: pos,
        sway: random(TWO_PI),
        swaySpeed: random(0.005, 0.015),
        leafCurve: random(0.3, 0.7)
      });
    }
  }

  getEndX() {
    return this.x + cos(this.angle + this.curveAmount * this.growth) * this.length * this.growth;
  }

  getEndY() {
    return this.y + sin(this.angle + this.curveAmount * this.growth) * this.length * this.growth;
  }

  grow() {
    this.growth = min(this.growth + this.growthSpeed, 1);

    if (this.growth >= 1 && this.depth < this.maxDepth && this.children.length === 0) {
      this.branch();
    }

    for (let child of this.children) {
      child.grow();
    }
  }

  branch() {
    let numBranches = random(1, 2);
    let spread = random(PI/4, PI/3);

    for (let i = 0; i < numBranches; i++) {
      if (random() < 0.7) {
        let angleOffset = spread * (i - (numBranches-1)/2) * random(0.6, 1.4);
        let newAngle = this.angle + angleOffset + random(-0.1, 0.1);
        let newLength = this.length * random(0.6, 0.8);
        let newWidth = this.branchWidth * random(0.5, 0.7);
        let child = new ForegroundBranch(
          this.getEndX(),
          this.getEndY(),
          newAngle,
          this.depth + 1,
          this.maxDepth,
          newLength,
          newWidth
        );
        this.children.push(child);
      }
    }
  }

  draw() {
    let endX = this.getEndX();
    let endY = this.getEndY();

    // Apply blur for foreground depth
    drawingContext.shadowBlur = this.blurAmount;
    drawingContext.shadowColor = 'rgba(0,0,0,0)';

    // Faded branch
    let alpha = map(this.depth, 0, this.maxDepth, 60, 120);
    stroke(red(this.color), green(this.color), blue(this.color), alpha);
    strokeWeight(this.branchWidth * 1.5);
    line(this.x, this.y, endX, endY);

    // Draw leaves with blur
    for (let leaf of this.leaves) {
      this.drawLeaf(leaf);
    }

    for (let child of this.children) {
      child.draw();
    }

    // Reset blur
    drawingContext.shadowBlur = 0;
  }

  drawLeaf(leaf) {
    var pos = leaf.position;
    let lx = lerp(this.x, this.getEndX(), pos);
    let ly = lerp(this.y, this.getEndY(), pos);

    let angle = lerp(this.angle, this.angle + this.curveAmount * this.growth, pos);
    var leafAngle = angle + leaf.angle + sin(leaf.sway + frameCount * leaf.swaySpeed) * 0.2;

    push();
    translate(lx, ly);
    rotate(leafAngle + leaf.rotation);

    var alpha = map(this.depth, 0, this.maxDepth, 40, 80);
    let startColor = color(leaf.gradient.start);
    let endColor = color(leaf.gradient.end);
    startColor.setAlpha(alpha);
    endColor.setAlpha(alpha);

    // Draw faded gradient leaf
    let steps = 6;
    for (let i = 0; i < steps; i++) {
      let t = i / steps;
      let yPos = -leaf.size * 0.5 + t * leaf.size;
      let widthAtY = leaf.size * 0.35 * (1 - abs(t - 0.5) * 1.2);

      let col = lerpColor(startColor, endColor, t);
      fill(col);
      noStroke();

      rectMode(CENTER);
      let curveOffset = sin(t * PI) * leaf.leafCurve * leaf.size * 0.3;
      beginShape();
      vertex(-widthAtY + curveOffset, yPos);
      vertex(-widthAtY * 0.5 + curveOffset, yPos + leaf.size * 0.08);
      vertex(0, yPos + leaf.size * 0.1);
      vertex(widthAtY * 0.5 + curveOffset, yPos + leaf.size * 0.08);
      vertex(widthAtY + curveOffset, yPos);
      endShape(CLOSE);
    }

    pop();
  }
}

class Stone {
  constructor(x, y, stoneWidth) {
    this.x = x;
    this.y = y;
    this.stoneWidth = stoneWidth;
    this.height = stoneWidth * random(0.2, 0.35);
    this.color = random(['#8a8a8a', '#9a9a9a', '#7a7a7a', '#aaaaaa', '#888888']);
    this.smoothness = random(0.7, 0.95);
    this.rotation = random(-0.05, 0.05);
    this.points = this.generateShape();
  }

  generateShape() {
    let pts = [];
    let numPoints = Math.floor(random(6, 10));
    for (let i = 0; i < numPoints; i++) {
      var angle = (i / numPoints) * TWO_PI;
      let radius = this.stoneWidth * random(0.4, 0.5) * this.smoothness;
      let x = this.x + cos(angle + this.rotation) * radius;
      let y = this.y + sin(angle + this.rotation) * radius * (this.height / this.stoneWidth);
      pts.push({x: x, y: y});
    }
    return pts;
  }

  draw() {
    push();

    // Shadow
    noStroke();
    fill(0, 20);
    beginShape();
    for (let p of this.points) {
      vertex(p.x + 3, p.y + 4);
    }
    endShape(CLOSE);

    // Stone body
    let baseColor = color(this.color);
    fill(baseColor);
    noStroke();
    beginShape();
    for (let p of this.points) {
      vertex(p.x, p.y);
    }
    endShape(CLOSE);

    // Highlight
    fill(255, 30);
    beginShape();
    for (let p of this.points) {
      let distVal = dist(p.x, p.y, this.x, this.y);
      let factor = 1 - distVal / (this.stoneWidth * 0.5);
      vertex(p.x - factor * 3, p.y - factor * 4);
    }
    endShape(CLOSE);

    // Edge highlight
    stroke(255, 20);
    strokeWeight(1.5);
    noFill();
    beginShape();
    for (let p of this.points) {
      var distVal = dist(p.x, p.y, this.x, this.y);
      if (distVal > this.stoneWidth * 0.2) {
        vertex(p.x - 1, p.y - 1);
      }
    }
    endShape(CLOSE);

    pop();
  }
}

class ZenPool {
  constructor(x, y, poolWidth, poolHeight) {
    this.x = x;
    this.y = y;
    this.poolWidth = poolWidth;
    this.poolHeight = poolHeight;
    this.color = random(['#2a4a5a', '#3a5a6a', '#1a3a4a', '#4a6a7a']);
    this.rippleOffset = random(TWO_PI);
    this.opacity = random(30, 60);
  }

  draw() {
    push();
    noStroke();

    // Pool body with gradient
    var col = color(this.color);
    col.setAlpha(this.opacity);
    fill(col);

    // Organic shape for pool
    beginShape();
    var steps = 30;
    for (let i = 0; i <= steps; i++) {
      var t = i / steps;
      var angle = t * TWO_PI;
      let xOff = sin(angle * 3 + this.rippleOffset) * this.poolWidth * 0.15;
      let yOff = cos(angle * 4 + this.rippleOffset * 1.5) * this.poolHeight * 0.15;
      let rx = this.poolWidth * 0.5 + xOff;
      let ry = this.poolHeight * 0.5 + yOff;
      let px = this.x + cos(angle) * rx;
      let py = this.y + sin(angle) * ry;
      vertex(px, py);
    }
    endShape(CLOSE);

    // Subtle ripples
    for (let i = 0; i < 3; i++) {
      var t = (i + 1) / 4;
      var radius = min(this.poolWidth, this.poolHeight) * 0.5 * t;
      let alphaVal = 30 * (1 - t);
      let rippleCol = color(200, 230, 255, alphaVal);
      stroke(rippleCol);
      strokeWeight(1);
      noFill();
      beginShape();
      for (let j = 0; j <= 20; j++) {
        var angle = (j / 20) * TWO_PI;
        let wave = sin(angle * 2 + frameCount * 0.01 + this.rippleOffset + i) * 3;
        var px = this.x + cos(angle) * (radius + wave);
        var py = this.y + sin(angle) * (radius + wave * 0.5);
        vertex(px, py);
      }
      endShape(CLOSE);
    }

    pop();
  }
}

class ZenBranch {
  constructor(x, y, angle, depth, maxDepth, length, branchWidth, maxLength) {
    this.x = x;
    this.y = y;
    this.angle = angle;
    this.depth = depth;
    this.maxDepth = maxDepth;
    this.length = min(length, maxLength);
    this.maxLength = maxLength;
    this.branchWidth = branchWidth;
    this.children = [];
    this.hasLeaves = false;
    this.leaves = [];
    this.growth = 0;
    this.growthSpeed = random(0.02, 0.05);
    this.curveAmount = random(-0.3, 0.3);
    this.color = random(BRANCH_COLORS);

    if (depth > maxDepth * 0.5 && random() < leafProbability) {
      this.hasLeaves = true;
      this.createLeaves();
    }
  }

  createLeaves() {
    var numLeaves = Math.floor(random(3, 7));
    for (let i = 0; i < numLeaves; i++) {
      var leafAngle = random(-0.8, 0.8);
      var leafSize = random(8, 16);
      var gradient = random(LEAF_GRADIENTS);
      var leafRotation = random(TWO_PI);

      var pos;
      if (random() < 0.4) {
        pos = 0.8 + random(0.2);
      } else {
        pos = random(0.3, 0.8);
      }

      this.leaves.push({
        angle: leafAngle,
        size: leafSize,
        gradient: gradient,
        rotation: leafRotation,
        position: pos,
        sway: random(TWO_PI),
        swaySpeed: random(0.01, 0.03),
        leafCurve: random(0.2, 0.6)
      });
    }
  }

  getEndX() {
    return this.x + cos(this.angle + this.curveAmount * this.growth) * this.length * this.growth;
  }

  getEndY() {
    return this.y + sin(this.angle + this.curveAmount * this.growth) * this.length * this.growth;
  }

  grow() {
    this.growth = min(this.growth + this.growthSpeed, 1);

    if (this.growth >= 1 && this.depth < this.maxDepth && this.children.length === 0) {
      this.branch();
    }

    for (let child of this.children) {
      child.grow();
    }
  }

  branch() {
    var numBranches = random(1, 3);
    var spread = random(PI/4, PI/2.5);

    for (let i = 0; i < numBranches; i++) {
      if (random() < branchProbability) {
        var angleOffset = spread * (i - (numBranches-1)/2) * random(0.6, 1.4);
        var newAngle = this.angle + angleOffset + random(-0.1, 0.1);
        var newLength = min(this.length * random(0.6, 0.85), this.maxLength * 0.8);
        var newWidth = this.branchWidth * random(0.5, 0.75);
        var child = new ZenBranch(
          this.getEndX(),
          this.getEndY(),
          newAngle,
          this.depth + 1,
          this.maxDepth,
          newLength,
          newWidth,
          this.maxLength * 0.8
        );
        this.children.push(child);
      }
    }

    if (this.depth < this.maxDepth - 1 && random() < 0.3) {
      var child = new ZenBranch(
        this.getEndX(),
        this.getEndY(),
        this.angle + random(-0.3, 0.3),
        this.depth + 1,
        this.maxDepth,
        min(this.length * random(0.4, 0.6), this.maxLength * 0.5),
        this.branchWidth * random(0.4, 0.6),
        this.maxLength * 0.6
      );
      this.children.push(child);
    }
  }

  draw() {
    var endX = this.getEndX();
    var endY = this.getEndY();

    // Branch shadow
    stroke(0, 30);
    strokeWeight(this.branchWidth + 2);
    line(this.x + 2, this.y + 2, endX + 2, endY + 2);

    // Main branch with texture
    for (let i = 0; i < 3; i++) {
      let offset = i - 1;
      stroke(this.color);
      strokeWeight(this.branchWidth - abs(offset) * 0.5);
      line(this.x + offset * 0.5, this.y + offset * 0.5, 
           endX + offset * 0.5, endY + offset * 0.5);
    }

    // Branch highlight
    stroke(255, 15);
    strokeWeight(this.branchWidth * 0.2);
    line(this.x - 1, this.y - 1, endX - 1, endY - 1);

    for (let leaf of this.leaves) {
      this.drawLeaf(leaf);
    }

    for (let child of this.children) {
      child.draw();
    }
  }

  drawLeaf(leaf) {
    var pos = leaf.position;
    var lx = lerp(this.x, this.getEndX(), pos);
    var ly = lerp(this.y, this.getEndY(), pos);

    var angle = lerp(this.angle, this.angle + this.curveAmount * this.growth, pos);
    var leafAngle = angle + leaf.angle + sin(leaf.sway + frameCount * leaf.swaySpeed) * 0.2;

    push();
    translate(lx, ly);
    rotate(leafAngle + leaf.rotation);
    scale(1 + sin(frameCount * 0.02 + leaf.sway) * 0.02);

    // Leaf shadow
    noStroke();
    fill(0, 15);
    beginShape();
    vertex(-leaf.size * 0.4 + 2, 2);
    vertex(0, -leaf.size * 0.6 + 2);
    vertex(leaf.size * 0.4 + 2, 2);
    vertex(0, leaf.size * 0.6 + 2);
    endShape(CLOSE);

    // Draw gradient leaf
    var steps = 8;
    var startColor = color(leaf.gradient.start);
    var endColor = color(leaf.gradient.end);

    for (let i = 0; i < steps; i++) {
      var t = i / steps;
      var yPos = -leaf.size * 0.6 + t * leaf.size * 1.2;
      var widthAtY = leaf.size * 0.4 * (1 - abs(t - 0.5) * 1.2);

      var col = lerpColor(startColor, endColor, t);
      var alpha = map(i, 0, steps, 200, 255);
      col.setAlpha(alpha);
      fill(col);
      noStroke();

      rectMode(CENTER);
      var curveOffset = sin(t * PI) * leaf.leafCurve * leaf.size * 0.3;
      beginShape();
      vertex(-widthAtY + curveOffset, yPos);
      vertex(-widthAtY * 0.5 + curveOffset, yPos + leaf.size * 0.08);
      vertex(0, yPos + leaf.size * 0.1);
      vertex(widthAtY * 0.5 + curveOffset, yPos + leaf.size * 0.08);
      vertex(widthAtY + curveOffset, yPos);
      endShape(CLOSE);
    }

    // Leaf vein
    stroke(0, 40);
    strokeWeight(0.7);
    line(0, -leaf.size * 0.5, 0, leaf.size * 0.5);

    for (let i = 0; i < 4; i++) {
      var t = (i + 1) / 5;
      var yPos = -leaf.size * 0.4 + t * leaf.size * 0.8;
      var widthAtY = leaf.size * 0.35 * (1 - abs(t - 0.5) * 1.2);
      stroke(0, 20);
      strokeWeight(0.3);
      line(0, yPos, widthAtY * 0.7, yPos + 2);
      line(0, yPos, -widthAtY * 0.7, yPos + 2);
    }

    // Leaf highlight
    fill(255, 25);
    noStroke();
    beginShape();
    vertex(-leaf.size * 0.1, -leaf.size * 0.3);
    vertex(0, -leaf.size * 0.45);
    vertex(leaf.size * 0.1, -leaf.size * 0.3);
    vertex(0, -leaf.size * 0.1);
    endShape(CLOSE);

    pop();
  }
}

class ZenPot {
  constructor(x, y, potSize) {
    this.x = x;
    this.y = y;
    this.potSize = potSize;
    this.shape = random(POT_SHAPES);
    this.gradient = random(POT_BASE_COLORS);
    this.decoration = random(['simple', 'stripes', 'dots', 'bands', 'waves']);
    this.metallic = random(0.3, 0.7);
    this.wobble = random(-0.3, 0.3);
    this.depthLayer = y;
  }

  getWidthAtHeight(t) {
    let baseWidth = this.potSize * 0.5;

    switch(this.shape) {
      case 'classic':
        return baseWidth * (1.2 - t * 0.5);
      case 'squat':
        return baseWidth * (1.4 - t * 0.3);
      case 'tall':
        return baseWidth * (1.0 - t * 0.7);
      case 'wavy':
        return baseWidth * (1.2 - t * 0.4 + sin(t * PI * 3 + this.wobble) * 0.15);
      case 'bulbous':
        let bulge = sin(t * PI) * 0.3;
        return baseWidth * (1.0 + bulge);
      case 'hourglass':
        let waist = sin(t * PI) * 0.3;
        return baseWidth * (0.7 + waist);
      case 'bowl':
        return baseWidth * (0.8 + t * 0.8);
      case 'tapered':
        return baseWidth * (1.3 - t * 0.8);
      case 'curvy':
        let curve = sin(t * PI * 1.5 + this.wobble) * 0.2;
        return baseWidth * (1.0 + curve);
      case 'barrel':
        let barrel = 1 - (t - 0.5) * (t - 0.5) * 2;
        return baseWidth * (0.7 + barrel * 0.4);
      default:
        return baseWidth * (1.2 - t * 0.5);
    }
  }

  draw() {
    push();

    // Pot shadow
    noStroke();
    fill(0, 25);
    let shadowWidth = this.getWidthAtHeight(1) * 1.2;
    ellipse(this.x + 5, this.y + this.potSize + 8, shadowWidth, 10);

    var startColor = color(this.gradient.start);
    var endColor = color(this.gradient.end);
    let gradientSteps = 30;

    // Draw pot body
    for (let i = 0; i < gradientSteps; i++) {
      var t = i / gradientSteps;
      var yPos = this.y + t * this.potSize;
      var widthAtY = this.getWidthAtHeight(t);

      var col = lerpColor(startColor, endColor, t);

      let sheen = sin(t * PI * 3 + this.metallic * 2) * 0.1 + 0.9;
      let r = red(col) * sheen;
      let g = green(col) * sheen;
      let b = blue(col) * sheen;

      let edgeDark = 1 - (1 - abs(t - 0.5) * 2) * 0.1;
      fill(r * edgeDark, g * edgeDark, b * edgeDark);

      noStroke();
      rectMode(CENTER);
      let heightSlice = this.potSize / gradientSteps + 1;
      rect(this.x, yPos, widthAtY, heightSlice);
    }

    // Pot rim
    let rimWidth = this.getWidthAtHeight(0);
    for (let i = 0; i < 8; i++) {
      var t = i / 8;
      var col = lerpColor(startColor, color(255, 255, 255, 50), t);
      fill(col);
      noStroke();
      rectMode(CENTER);
      var yPos = this.y - 2 + t * 8;
      rect(this.x, yPos, rimWidth + 6 - t * 2, 1.5);
    }

    fill(255, 40);
    rect(this.x - rimWidth * 0.2, this.y - 1, rimWidth * 0.4, 2);

    let bottomWidth = this.getWidthAtHeight(1);
    for (let i = 0; i < 6; i++) {
      var t = i / 6;
      var col = lerpColor(endColor, color(0, 0, 0, 100), t);
      fill(col);
      noStroke();
      rectMode(CENTER);
      var yPos = this.y + this.potSize + t * 6;
      rect(this.x, yPos, bottomWidth - t * 3, 1.5);
    }

    this.drawDecoration(startColor, endColor);

    stroke(255, 20);
    strokeWeight(2);
    noFill();
    var steps = 20;
    for (let i = 0; i < steps; i++) {
      var t = i / steps;
      var yPos = this.y + t * this.potSize;
      var widthAtY = this.getWidthAtHeight(t);
      var alpha = map(sin(t * PI), 0, 1, 10, 30);
      stroke(255, alpha);
      point(this.x - widthAtY * 0.5, yPos);
    }

    pop();
  }

  drawDecoration(startColor, endColor) {
    let darkColor = lerpColor(startColor, color(0), 0.3);
    let lightColor = lerpColor(startColor, color(255), 0.2);

    strokeWeight(2);
    noFill();

    if (this.decoration === 'stripes') {
      for (let i = 0; i < 6; i++) {
        var t = i / 5;
        var yPos = this.y + t * this.potSize;
        var widthAtY = this.getWidthAtHeight(t);
        var col = lerpColor(darkColor, lightColor, t);
        col.setAlpha(80);
        stroke(col);
        strokeWeight(2);
        let halfWidth = widthAtY * 0.4;
        let xOffset = sin(t * PI * 2 + this.wobble) * halfWidth * 0.2;
        line(this.x - halfWidth + xOffset, yPos, this.x + halfWidth + xOffset, yPos);
      }
    } else if (this.decoration === 'dots') {
      for (let i = 0; i < 8; i++) {
        var t = (i + 0.5) / 8;
        var yPos = this.y + t * this.potSize;
        var widthAtY = this.getWidthAtHeight(t);
        let xPos = this.x + (t - 0.5) * widthAtY * 0.6;
        let dotSize = map(sin(t * PI * 2), 0, 1, 2, 5);
        var col = lerpColor(lightColor, darkColor, t);
        col.setAlpha(120);
        fill(col);
        noStroke();
        circle(xPos, yPos, dotSize);
      }
    } else if (this.decoration === 'bands') {
      for (let i = 0; i < 4; i++) {
        var t = (i + 0.5) / 4;
        var yPos = this.y + t * this.potSize;
        var widthAtY = this.getWidthAtHeight(t);
        var col = lerpColor(lightColor, darkColor, t);
        col.setAlpha(80);
        stroke(col);
        strokeWeight(3);
        var halfWidth = widthAtY * 0.4;
        line(this.x - halfWidth, yPos, this.x + halfWidth, yPos);
      }
    } else if (this.decoration === 'waves') {
      stroke(lightColor);
      strokeWeight(1.5);
      for (let i = 0; i < 5; i++) {
        var t = (i + 0.5) / 5;
        var yPos = this.y + t * this.potSize;
        var widthAtY = this.getWidthAtHeight(t);
        var halfWidth = widthAtY * 0.4;
        var col = lerpColor(lightColor, darkColor, t);
        col.setAlpha(70);
        stroke(col);
        beginShape();
        for (let x = -halfWidth; x <= halfWidth; x += 2) {
          var wave = sin(x * 0.1 + t * 5 + this.wobble) * 3;
          vertex(this.x + x, yPos + wave);
        }
        endShape();
      }
    }
  }
}

function setup() {
  createCanvas(windowWidth, windowHeight);
  pixelDensity(1);
  angleMode(RADIANS);

  // Get canvas dimensions after creation
  let canvasWidth = width;
  let canvasHeight = height;

  generateZenGarden(canvasWidth, canvasHeight);

  describe("Zen Pot Garden with stones, pools, and foreground depth");
}

function generateZenGarden(cWidth, cHeight) {
  branches = [];
  pots = [];
  stones = [];
  zenPools = [];
  foregroundBranches = [];

  // Use passed dimensions or fallback to window dimensions
  let w = cWidth || windowWidth;
  let h = cHeight || windowHeight;

  // Create foreground branches (from sides)
  let maxBranchLength = min(w, h) * 0.3;
  let sideBranches = Math.floor(random(3, 6));

  for (let i = 0; i < sideBranches; i++) {
    let fromLeft = random() > 0.5;
    var x = fromLeft ? -20 : w + 20;
    var y = random(h * 0.2, h * 0.8);
    var angle = fromLeft ? random(0.2, 0.8) : random(PI - 0.8, PI - 0.2);
    let length = random(maxBranchLength * 0.3, maxBranchLength * 0.6);
    let branchWidth = random(4, 10);
    let depth = Math.floor(random(3, 6));

    let branch = new ForegroundBranch(
      x, y, angle, 0, depth, length, branchWidth
    );
    foregroundBranches.push(branch);
  }

  // Create zen pools
  let numPools = Math.floor(random(2, 4));
  for (let i = 0; i < numPools; i++) {
    var x = random(w * 0.1, w * 0.9);
    var y = random(h * 0.3, h * 0.8);
    let poolWidth = random(80, 200);
    let poolHeight = random(40, 120);
    let pool = new ZenPool(x, y, poolWidth, poolHeight);
    zenPools.push(pool);
  }

  // Create pots and stones
  let numPots = Math.floor(random(3, 6));
  let potSize = min(w, h) * 0.12;

  for (let i = 0; i < numPots; i++) {
    var x, y, size;
    let attempts = 0;
    let validPosition = false;

    while (!validPosition && attempts < 50) {
      x = random(w * 0.1, w * 0.9);
      y = random(h * 0.45, h * 0.85);
      size = potSize * random(0.7, 1.5);

      validPosition = true;

      for (let pot of pots) {
        let minDist = (size + pot.potSize) * 0.9;
        if (dist(x, y, pot.x, pot.y) < minDist) {
          validPosition = false;
          break;
        }
      }
      attempts++;
    }

    if (validPosition) {
      let pot = new ZenPot(x, y, size);
      pots.push(pot);

      // Create stone under pot
      let stoneWidth = size * random(1.0, 1.6);
      let stoneY = y + size * 0.9;
      let stone = new Stone(x, stoneY, stoneWidth);
      stones.push(stone);
    }
  }

  // Sort pots by y position (bottom = closer = drawn last)
  pots.sort((a, b) => a.depthLayer - b.depthLayer);

  // Create branches for each pot
  let maxBranchLen = min(w, h) * 0.2;

  for (let pot of pots) {
    var numBranches = Math.floor(random(1, 3));
    let baseLength = pot.potSize * random(0.6, 1.2);

    for (let j = 0; j < numBranches; j++) {
      var angle = random(-PI/2.5, PI/2.5) - PI/2;
      var length = min(baseLength * random(0.7, 1.3), maxBranchLen * random(0.6, 1.0));
      var branchWidth = random(2, 5);
      var depth = Math.floor(random(4, maxDepth + 1));

      var branch = new ZenBranch(
        pot.x + random(-pot.potSize * 0.15, pot.potSize * 0.15),
        pot.y - random(3, 15),
        angle,
        0,
        depth,
        length,
        branchWidth,
        maxBranchLen * 0.8
      );
      branches.push(branch);
    }
  }
}

function draw() {
  // Warm grey gradient background
  for (let y = 0; y < height; y++) {
    let inter = y / height;
    let grey = lerp(140, 60, inter);
    let warmth = sin(y * 0.005) * 3;
    stroke(grey + warmth + 5);
    line(0, y, width, y);
  }

  // Subtle texture
  noStroke();
  for (let i = 0; i < 80; i++) {
    var x = random(width);
    var y = random(height);
    let size = random(0.5, 2);
    fill(200, random(5, 15));
    circle(x, y, size);
  }

  // Draw zen pools (behind everything)
  for (let pool of zenPools) {
    pool.draw();
  }

  // Draw stones (behind pots)
  for (let stone of stones) {
    stone.draw();
  }

  // Draw branches (behind pots)
  for (let branch of branches) {
    branch.grow();
    branch.draw();
  }

  // Draw pots in order (bottom pots on top)
  for (let pot of pots) {
    pot.draw();
  }

  // Draw foreground branches (on top, blurred)
  for (let branch of foregroundBranches) {
    branch.grow();
    branch.draw();
  }

  drawUI();
}

function drawUI() {
  fill(255, 80);
  noStroke();
  textAlign(CENTER, BOTTOM);
  textSize(12);
  text('Zen Pot Garden • Click to generate new', width/2, height - 20);

  fill(255, 40);
  textSize(10);
  text('Press SPACE for new garden • R to reset • F for fullscreen', width/2, height - 40);

  textSize(10);
  text(`Pots: ${pots.length} • Stones: ${stones.length} • Pools: ${zenPools.length}`, width/2, height - 55);
}

function mousePressed() {
  generateZenGarden(width, height);
}

function keyPressed() {
  if (key === ' ' || key === 'r' || key === 'R') {
    generateZenGarden(width, height);
  }

  if (key === 'f' || key === 'F') {
    let fs = fullscreen();
    fullscreen(!fs);
    if (!fs) {
      resizeCanvas(windowWidth, windowHeight);
    }
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  generateZenGarden(width, height);
}

